(function(){'use strict';
const $=id=>document.getElementById(id),section=$('shopCatalogue');if(!section)return;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v==null?'Not set':new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(v/100),date=v=>v?new Date(v).toLocaleString('en-GB'):'Not checked yet';
let artwork=null;const artworkReady=import('./shopProductIllustrations.js?v=2').then(m=>{artwork=m;}).catch(()=>{});
let review=null;const reviewReady=import('./shopCatalogueReview.mjs?v=6').then(m=>{review=m;});
let shipping=null;const shippingReady=import('./shopShippingEstimates.mjs?v=1').then(m=>{shipping=m;});
let state=null,selected='',dirty=false,busy=false,seq=0,checking=false,poll;
const message=(s,error=false)=>{const e=$('shopCatalogueStatus');e.textContent=s;e.setAttribute('role',error?'alert':'status');};
async function request(path='',body){const r=await InventoryAPI.request('/admin/shop-catalogue'+path,body===undefined?undefined:{method:'POST',body:JSON.stringify(body)});if(!r?.success)throw Error(r?.error||'Install the latest Shop backend update to use product management.');return r;}
function input(name,label,value='',type='text',extra=''){return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value??'')}" ${extra}></label>`;}
const pounds=(n)=>n==null?'':(n/100).toFixed(2),dims=d=>(d||[]).join(' × ');
const checkbox=(name,label,on)=>`<label class="sc-check"><input name="${name}" type="checkbox" ${on?'checked':''}>${esc(label)}</label>`;
const illustration=p=>{const n=(p.id+' '+p.name+' '+p.category).toLowerCase();return /printer/.test(n)?'printer':/box/.test(n)?'boxes':/bag/.test(n)?'bags':/label/.test(n)?'labels':/tape|dispenser/.test(n)?'tape':'wrap';};
function photo(p,large=false,variant=null){const image=artwork?.productImage(p,variant)||{src:p.image_url||'',illustration:false};return `<figure class="sc-photo ${large?'sc-photo-large':''}"><img src="${esc(image.src||'assets/shop-drafts/'+illustration(p)+'.svg')}" alt="${esc((image.illustration?'Illustration of ':'')+p.name+(variant?' — '+artwork?.variantAnnotation(variant):''))}" loading="lazy"><figcaption>${image.illustration?'Product illustration · appearance may vary':image.src?'Product photo':'Draft illustration · product photo needed'}${variant?'<strong class="sc-image-annotation">Selected option: '+esc(artwork?.variantAnnotation(variant)||variant.name)+'</strong><span>'+esc(variant.sku)+'</span>':''}</figcaption></figure>`;}
function supplierBasis(v){const units=v.supplier_price_units??1,min=v.supplier_min_order_qty??1;return `${units===1?'Per '+esc(v.supplier_unit_name==='boxes'?'box':'unit'):'Per pack of '+units} · minimum ${min}${units===1?' units':' packs'} (${units*min} ${esc(v.supplier_unit_name||'units')})<br>Minimum purchase inc VAT: ${v.supplier_minimum_pence==null?'Check prices to calculate':money(v.supplier_minimum_pence)}<br>We sell: ${v.sale_units_per_pack??1} ${esc(v.supplier_unit_name||'units')} per pack<br>Customer minimum: ${v.min_order_qty??Math.ceil(units*min/(v.sale_units_per_pack??1))} selling packs`;}
function profitText(v){const p=review?.productProfit(v);return p?money(p.pence)+' / pack · '+p.margin.toFixed(1)+'%'+(p.estimated?' · Estimated':''):'Cost or selling price needed';}
function productProfitText(p){const variants=state.variants.filter(v=>v.product_id===p.id),profits=variants.map(v=>review?.productProfit(v)).filter(Boolean);if(!profits.length)return 'Profit: cost or selling price needed';const min=Math.min(...profits.map(p=>p.pence)),max=Math.max(...profits.map(p=>p.pence));return 'Profit: '+money(min)+(max===min?'':' – '+money(max))+' / pack'+(profits.some(p=>p.estimated)?' · Estimated':'')+(profits.length<variants.length?' · Some costs missing':'');}
function shippingReference(v,compact=false){
 const e=shipping?.estimateFor(v);if(!e)return '';
 const sameWeight=v.weight_g===e.weight_g,sameSize=JSON.stringify(v.dimensions_mm)===JSON.stringify(e.dimensions_mm),usingEstimate=sameWeight||sameSize;
 const label=usingEstimate?(v.shipping_verified?'Shipping estimates reviewed':'Estimated shipping — review required'):'Shipping estimate available';
 return `<details class="sc-shipping-reference"><summary>${esc(label)}${e.confidence==='low'?' · Low confidence':''}</summary><p>Reference packed weight: <strong>${e.weight_g}g</strong><br>Reference packed dimensions: <strong>${e.dimensions_mm?dims(e.dimensions_mm)+' mm':'Unknown — enter actual pack dimensions'}</strong>${e.supplier_net_weight_g?'<br>Supplier roll weight before protection: '+e.supplier_net_weight_g+'g':''}</p><p>${esc(e.method)}</p><p>Weight includes a 5% protective allowance (at least 15g). Estimated dimensions describe the supplied selling pack.</p>${e.dimensions_unknown?'<p class="sc-warning">Supplier model dimensions are unpublished. Enter the actual packed dimensions before calculated postage.</p>':e.manual_delivery?'<p class="sc-warning">Reference pack exceeds Royal Mail medium-parcel dimensions. Check actual packing or arrange another delivery service.</p>':''}<p>${e.sources.map(k=>shipping.shippingEstimates.sources[k]).map(src=>'<a href="'+esc(src.url)+'" target="_blank" rel="noopener">Source ↗</a> '+esc(src.basis)).join('<br>')}</p><small>Researched ${shipping.shippingEstimates.checked_on}. Reference estimates can be replaced by your measurements.</small></details>`;
}
const courierNames={inpost:'InPost',dpd:'DPD',evri:'Evri',parcelforce:'Parcelforce'};
const rateColumns=['code','name','tier','price_gbp','max_weight_kg','max_length_cm','max_width_cm','max_height_cm','max_length_plus_girth_cm','volumetric_divisor','coverage'];
function csvCell(v){return '"'+String(v??'').replaceAll('"','""')+'"';}
function carrierCSV(rates=[]){return rateColumns.join(',')+'\n'+rates.map(r=>[r.code,r.name,r.tier,(r.price_pence/100).toFixed(2),r.max_g/1000,...r.dimensions_mm.map(n=>n/10),r.max_girth_mm?r.max_girth_mm/10:'',r.volumetric_divisor||'',r.coverage||'UK'].map(csvCell).join(',')).join('\n');}
function renderCarriers(){
 if(!Array.isArray(state.carriers))return;
 if(!$('scCouriers')){const div=document.createElement('div');div.id='scCouriers';$('shopRoyalRates').after(div);$('shopRoyalRates').closest('details').querySelector('summary').textContent='Delivery couriers & rate cards';}
 $('scCouriers').innerHTML='<p>Standard delivery compares suitable enabled couriers. Express uses services marked Express. Prices must include VAT and all charges for the stated home-delivery coverage. Regional services are only used after the customer enters a qualifying postcode. Services requiring a destination-specific quote need a suitable all-in rate card before use. Uploading a guide never books or pays for delivery.</p><div class="sc-checks">'+state.carriers.map(c=>'<article class="sc-check-card"><h3>'+esc(c.name)+'</h3><strong>'+(!c.enabled?'Disabled':c.expired?'Rates need refreshing':c.rates.length+' active bands')+'</strong><p>'+(c.automatic?'Automatic public home-delivery price checks.':'Manual rate card: quoted/from prices are not imported automatically.')+'<br>Last confirmed: '+date(c.checked_at)+'<br>Valid until: '+date(c.valid_until)+'</p><a href="'+esc(c.source_url||c.url)+'" target="_blank" rel="noopener">Open courier source ↗</a><p><button type="button" data-carrier-edit="'+esc(c.id)+'">Manage / upload rates</button></p></article>').join('')+'</div><div id="scCarrierEditor"></div>';
}
function carrierRow(r={}){const row=document.createElement('tr');row.dataset.carrierRow='';row.innerHTML='<td>'+input('code','Code',r.code||'')+input('name','Service name',r.name||'')+'<label>Tier<select name="tier"><option value="standard">Standard</option><option value="express">Express</option></select></label><label>Coverage<select name="coverage"><option value="UK">UK-wide (all charges included)</option><option value="MAINLAND">Mainland area only</option></select></label></td><td>'+input('price_gbp','All-in price (£)',r.price_pence==null?'':pounds(r.price_pence),'number','min="0.50" max="1000" step="0.01" required')+input('max_weight_kg','Maximum weight (kg)',r.max_g==null?'':r.max_g/1000,'number','min="0.001" max="70" step="0.001" required')+'</td><td>'+['Length','Width','Height'].map((n,i)=>input('dim'+i,'Maximum '+n.toLowerCase()+' (cm)',r.dimensions_mm?.[i]==null?'':r.dimensions_mm[i]/10,'number','min="0.1" max="500" step="0.1" required')).join('')+'</td><td>'+input('max_girth_cm','Maximum length + girth (cm, optional)',r.max_girth_mm?r.max_girth_mm/10:'','number','min="0" max="1500" step="0.1"')+input('volumetric_divisor','Volumetric divisor (optional)',r.volumetric_divisor||'','number','min="0" max="100000" step="1"')+'<button type="button" data-remove-rate>Remove band</button></td>';row.querySelector('[name=tier]').value=r.tier||'standard';row.querySelector('[name=coverage]').value=r.coverage||'UK';return row;}
function editCarrier(id){
 if(busy||!state)return;if(dirty&&!confirm('Discard unsaved changes?'))return;dirty=false;const c=state.carriers.find(c=>c.id===id);if(!c)return;let documentHash=c.document_sha256||null;
 $('scCarrierEditor').innerHTML='<form id="scCarrierForm"><fieldset><h3>'+esc(c.name)+' rate card</h3><div class="sc-grid">'+input('source_url','Source / booking reference',c.source_url||c.url,'url','required')+input('valid_until','Rates valid until',new Date(c.valid_until&&new Date(c.valid_until)>Date.now()?c.valid_until:Date.now()+30*86400000).toISOString().slice(0,16),'datetime-local','required')+'</div>'+checkbox('enabled','Use these rates at checkout',c.enabled)+'<label>Upload PDF or CSV (maximum 2.5 MB)<input type="file" name="guide" accept=".pdf,.csv,application/pdf,text/csv"></label><button type="button" id="scReadCarrier">Read uploaded guide</button> <button type="button" id="scDownloadCarrier">Download CSV template</button><p>PDF text appears below for review. Enter the applicable price bands, or import a completed CSV. Prices must be the amounts you can actually book, including VAT, fuel and location surcharges. A maximum length alone is not enough: enter all three dimensional limits and any length-plus-girth limit from the service guide.</p><label id="scCarrierTextLabel" hidden>Uploaded guide text<textarea id="scCarrierText" readonly></textarea></label><div class="table-wrap"><table><tbody id="scCarrierRows"></tbody></table></div><button type="button" id="scAddCarrierRate">Add price band</button>'+checkbox('confirmed','I checked these current prices and size/weight limits against the source.',false)+checkbox('all_in_uk_home','These are all-in home-delivery prices for the selected coverage, including VAT and every applicable surcharge. They are not locker-collection, from, or destination-specific prices.',false)+'<button type="submit">Confirm and save courier rates</button><button type="button" id="scCloseCarrier">Close</button></fieldset></form>';
 const rows=$('scCarrierRows');(c.rates.length?c.rates:[{coverage:c.id==='inpost'?'MAINLAND':'UK'}]).forEach(r=>rows.append(carrierRow(r)));
 $('scAddCarrierRate').onclick=()=>{rows.append(carrierRow({coverage:c.id==='inpost'?'MAINLAND':'UK'}));dirty=true;};rows.onclick=e=>{const b=e.target.closest('[data-remove-rate]');if(b){b.closest('tr').remove();dirty=true;}};
 $('scDownloadCarrier').onclick=()=>{const url=URL.createObjectURL(new Blob([carrierCSV(c.rates)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='InventoryOS-'+c.name+'-rates.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 $('scReadCarrier').onclick=async()=>{if(busy)return;const form=$('scCarrierForm'),file=form.elements.guide.files[0];if(!file||file.size>2500000){message('Choose a PDF or CSV no larger than 2.5 MB.',true);return;}busy=true;seq++;form.querySelector('fieldset').disabled=true;try{const body={carrier:id};if(/\.csv$/i.test(file.name))body.csv=await file.text();else body.pdf_base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(Error('Could not read that file.'));r.readAsDataURL(file);});const r=(await request('/carriers/preview',body)).result;if(!form.isConnected)return;documentHash=r.document_sha256;$('scCarrierTextLabel').hidden=!r.text;$('scCarrierText').value=r.text||'';if(r.rates.length){rows.replaceChildren(...r.rates.map(carrierRow));}form.elements.confirmed.checked=false;form.elements.all_in_uk_home.checked=false;dirty=true;message(r.rates.length?r.rates.length+' price bands loaded. Review every field and confirm before saving.':r.note);}catch(e){message(e.message,true);}finally{busy=false;form.querySelector('fieldset').disabled=false;}};
 $('scCloseCarrier').onclick=()=>{if(!dirty||confirm('Discard unsaved courier changes?')){dirty=false;$('scCarrierEditor').innerHTML='';}};
 $('scCarrierForm').onsubmit=e=>{e.preventDefault();const form=e.target,f=new FormData(form),rates=[...rows.querySelectorAll('[data-carrier-row]')].map(row=>{const val=n=>row.querySelector('[name="'+n+'"]').value,num=(n,scale=1)=>val(n)===''?null:Math.round(Number(val(n))*scale);return {code:val('code').trim(),name:val('name').trim(),tier:val('tier'),price_pence:num('price_gbp',100),max_g:num('max_weight_kg',1000),dimensions_mm:[0,1,2].map(i=>num('dim'+i,10)),max_girth_mm:num('max_girth_cm',10),volumetric_divisor:num('volumetric_divisor'),delivery_mode:'home',coverage:val('coverage')};});save('/carriers/save',{carrier:id,version:c.version,source_url:f.get('source_url'),valid_until:new Date(f.get('valid_until')).toISOString(),enabled:f.has('enabled'),confirmed:f.has('confirmed'),all_in_uk_home:f.has('all_in_uk_home'),document_sha256:documentHash,rates},form);};
 $('scCarrierEditor').scrollIntoView({behavior:'smooth',block:'start'});
}
function supplierAvailabilityText(v){if(v.availability_mode==='own'||v.fulfilment_mode==='own')return 'Own-stock fulfilment (legacy)';return (v.availability_status==='available'?'Supplier: available to order':v.availability_status==='unavailable'?'Supplier: currently unavailable':'Supplier availability needs checking')+(v.supplier_stock_checked_at?' · '+date(v.supplier_stock_checked_at):'');}
function confirmSupplierAvailability(v){if(busy)return;if(dirty){message('Save or close your current changes first.',true);return;}$('scSupplierEditor').innerHTML='<form id="scSupplierForm"><fieldset><h4>Confirm supplier availability</h4><p>Use this only after checking the supplier. Automatic checks are preferred where supported. Confirmation expires after 48 hours.</p><label>Supplier status<select name="available"><option value="true">Available to order from supplier</option><option value="false">Currently unavailable from supplier</option></select></label>'+input('quantity','Exact supplier quantity in OUR selling packs (optional)','', 'number','min="0" max="1000000" step="1"')+checkbox('confirmed','I have checked the supplier availability for this exact variant and selling pack.',false)+'<button type="submit">Confirm supplier availability</button></fieldset></form>';$('scSupplierForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);save('/supplier-stock/confirm',{id:v.id,version:v.version,available:f.get('available')==='true',quantity_packs:f.get('quantity')===''?null:Number(f.get('quantity')),confirmed:f.has('confirmed')},e.target,()=>showProduct(v.product_id));};}

function productVariants(p){return state.variants.filter(v=>v.product_id===p.id);}
function preparedProduct(p){const image=artwork?.productImage(p);return {...p,image_url:(p.id==='jadens-668bt'?image?.src:p.image_url)||image?.src||'',image_rights:p.image_rights||(image?.illustration?artwork.illustrationRights:'')};}
function productBlockers(p){return review.productPublicationProblems(preparedProduct(p),productVariants(p));}
function filterName(){return $('scProductFilter')?.value||'all';}
function matchesFilter(p,filter=filterName()){return review.catalogueMatch(p,productVariants(p),filter,preparedProduct(p));}
function shownVariants(p){const f=filterName(),all=productVariants(p);return ['all','draft','published','ready','image','rights'].includes(f)?all:all.filter(v=>review.variantMatches(v,f));}
function publicationPanel(p){
 const blockers=productBlockers(p),variants=productVariants(p),visible=variants.filter(v=>!review.approvalProblem(v)&&!review.needsApproval(v)).length;
 return `<div class="sc-publication"><strong>${p.published?'Published':blockers.length?'Draft — needs attention':'Approved — ready to publish'}</strong><p>${p.published?'Published products appear in the shop. Only approved variants are shown. Customers order against supplier availability; you buy stock after their order.':'Approval checks variant details. Publish the product to make it appear in your shop.'}</p>${p.id&&!p.published?'<button type="button" id="scPublishProduct" '+(blockers.length?'disabled':'')+'>Publish this product</button>':''}${blockers.length?'<details '+(filterName()!=='all'?'open':'')+'><summary>'+blockers.length+' publication checks need attention</summary><ul>'+blockers.map(b=>'<li>'+esc(b)+'</li>').join('')+'</ul></details>':''}${p.published&&visible===0?'<p class="sc-warning">No approved variants are currently visible in the shop.</p>':''}${variants.some(v=>v.availability_status!=='available')?'<p class="sc-warning">Some supplier availability needs checking. Run Supplier prices & availability, or confirm the exact variant manually.</p>':''}</div>`;
}
function renderFilters(){
 if(!$('scProductFilter')){
  const wrap=document.createElement('div');wrap.className='sc-filters';wrap.innerHTML='<label>Filter products<select id="scProductFilter"></select></label><button type="button" id="scClearFilter">Clear filters</button>';
  $('shopProductSearch').closest('label').after(wrap);
  $('scProductFilter').onchange=()=>{render();if(selected&&!dirty){const p=state.products.find(p=>p.id===selected);if(p&&matchesFilter(p))showProduct(selected);else{selected='';$('shopProductEditor').hidden=true;render();}}};
  $('scClearFilter').onclick=()=>{$('scProductFilter').value='all';$('shopProductSearch').value='';render();if(selected&&!dirty)showProduct(selected);};
 }
 const active=filterName();$('scProductFilter').innerHTML=review.catalogueFilters.map(([value,label])=>'<option value="'+value+'">'+label+' ('+state.products.filter(p=>matchesFilter(p,value)).length+')</option>').join('');$('scProductFilter').value=active;
 if(!$('scPublishAll')){
  const b=document.createElement('button');b.type='button';b.id='scPublishAll';b.textContent='Publish approved products';b.onclick=()=>publishApproved();$('scFillShipping').after(b);
  const summary=document.createElement('p');summary.id='scPublicationSummary';summary.className='sc-profit-note';$('shopProductSearch').closest('label').before(summary);
 }
 const drafts=state.products.filter(p=>!p.published),ready=drafts.filter(p=>!productBlockers(p).length);
 $('scPublicationSummary').textContent=state.products.filter(p=>p.published).length+' published · '+ready.length+' approved products ready to publish · '+(drafts.length-ready.length)+' drafts need attention. Approval and publication are separate.';
}
async function publishApproved(productId){
 if(busy||!state)return;if(dirty){message('Save or close your unsaved changes before publishing.',true);return;}
 const drafts=state.products.filter(p=>(!productId||p.id===productId)&&!p.published),eligible=drafts.filter(p=>!productBlockers(p).length),skipped=drafts.length-eligible.length;
 if(!eligible.length){message(drafts.length?'No products are ready to publish. Use Needs attention to see missing details or delivery checks.':'These products are already published.',!!drafts.length);return;}
 if(!confirm('Publish '+eligible.length+' approved products to your public shop?\n\nThis saves the product images and their permission references already shown in admin, including your supplied illustrations. Only products whose variants pass all approval and delivery checks will be sent.\n'+skipped+' incomplete products will remain drafts.'))return;
 busy=true;seq++;const controls=[...section.querySelectorAll('button,input,select,textarea')].map(e=>[e,e.disabled]);controls.forEach(([e])=>e.disabled=true);let published=0,failed=[],attempted=0,consecutive=0;
 try{for(const p of eligible){message('Publishing '+(++attempted)+' of '+eligible.length+' products…');try{await request('/products',{...preparedProduct(p),published:true});published++;consecutive=0;}catch(e){failed.push(p.name+': '+e.message);if(++consecutive>=3)break;}}}
 finally{busy=false;controls.forEach(([e,disabled])=>{if(e.isConnected)e.disabled=disabled;});await load(true);if(selected)showProduct(selected);message(published+' products published · '+skipped+' drafts need attention · '+(eligible.length-published)+' not published'+(failed.length?'. '+failed.join(' | '):'. Refresh your shop to see published products.'),failed.length>0);}
}

async function fillShipping(productId){
 if(busy||!state)return;if(dirty){message('Save or close your unsaved changes first.',true);return;}
 const missing=state.variants.filter(v=>(!productId||v.product_id===productId)&&(v.weight_g==null||v.dimensions_mm==null)),plans=missing.map(v=>({v,body:shipping.shippingFill(v)})).filter(p=>p.body),skipped=missing.length-plans.length;
 if(!plans.length){message(missing.length?'No matching estimates for these variants. Check SKU and selling-pack size; confirmed measurements are preserved.':'All variants in this selection already have weights and dimensions.',!!missing.length);return;}
 if(!confirm('Fill missing weights and dimensions for '+plans.length+' variants '+(productId?'in this product':'across the catalogue')+'?\n\nThese are supplier/comparable-product estimates, scaled to each selling pack, with protective allowances. Existing measurements and confirmed shipping details are kept. Shipping remains unconfirmed for your review. Prices, stock and pack quantities stay the same.'))return;
 busy=true;seq++;const controls=[...section.querySelectorAll('button,input,select,textarea')].map(e=>[e,e.disabled]);controls.forEach(([e])=>e.disabled=true);let saved=0,failed=[],attempted=0,consecutive=0;
 try{for(const {v,body} of plans){message('Filling shipping estimates '+(++attempted)+' of '+plans.length+'…');try{await request('/variants',body);saved++;consecutive=0;}catch(e){failed.push(v.name+': '+e.message);if(++consecutive>=3)break;}}}
 finally{busy=false;controls.forEach(([e,disabled])=>{if(e.isConnected)e.disabled=disabled;});await load(true);if(selected)showProduct(selected);message(saved+' shipping estimates saved · '+skipped+' skipped · '+(plans.length-saved)+' not confirmed'+(failed.length?'. '+failed.slice(0,3).join(' | '):'. '+(plans.filter(p=>p.body.dimensions_mm==null).length?plans.filter(p=>p.body.dimensions_mm==null).length+' still needs actual pack dimensions. ':'')+'Review the estimates before approving shipping.'),failed.length>0);}
}
async function approveAll(productId,pricesOnly=false){
 if(busy||!state)return;if(dirty){message('Save or close your unsaved changes before approving.',true);return;}
 const pending=state.variants.filter(v=>(!productId||v.product_id===productId)&&(pricesOnly?v.price_estimated===true:review.needsApproval(v))),eligible=pending.filter(v=>!(pricesOnly?review.priceApprovalProblem(v):review.approvalProblem(v))),skipped=pending.length-eligible.length;
 if(!eligible.length){const counts=new Map();for(const v of pending)for(const problem of pricesOnly?[review.priceApprovalProblem(v)].filter(Boolean):review.approvalProblems(v))counts.set(problem,(counts.get(problem)||0)+1);message(pending.length?(pricesOnly?'No selling prices can be approved yet. ':'No complete variants can be approved yet. ')+[...counts].map(([problem,n])=>n+' × '+problem).join(' · ')+(pricesOnly?'':' · Use Approve all prices to review suggested prices separately.'):(pricesOnly?'All selling prices in this selection are already approved.':'All variants in this selection are already approved. Use Publish approved products to make them appear in the shop.'),!!pending.length);return;}
 const scope=productId?'for this product':'across the whole catalogue';
 const confirmation=pricesOnly?'Approve '+eligible.length+' selling prices '+scope+'?\n\nConfirm you have reviewed these prices against the saved supplier costs and delivery costs. Supplier-cost and shipping checks remain separate.': 'Approve '+eligible.length+' variants '+scope+'?\n\nThis confirms you have checked their supplier costs and pack contents, reviewed their packed weights and dimensions (including any marked estimates), selling prices and delivery costs.';
 if(!confirm(confirmation+'\n'+skipped+' incomplete variants will be skipped. Products are published separately.'))return;
 busy=true;seq++;const controls=[...section.querySelectorAll('button,input,select,textarea')].map(e=>[e,e.disabled]);controls.forEach(([e])=>e.disabled=true);let approved=0,failed=[],attempted=0,consecutive=0;
 try{for(const v of eligible){message('Approving '+(++attempted)+' of '+eligible.length+'…');try{await request('/variants',{...v,price_confirmed:true,...(pricesOnly?{}:{cost_verified:true,shipping_verified:true})});approved++;consecutive=0;}catch(e){failed.push(v.name+': '+e.message);if(++consecutive>=3)break;}}}
 finally{busy=false;controls.forEach(([e,disabled])=>{if(e.isConnected)e.disabled=disabled;});await load(true);if(selected)showProduct(selected);message(approved+(pricesOnly?' selling prices approved · ':' approved · ')+skipped+' incomplete · '+(eligible.length-approved)+' not approved'+(failed.length?'. '+failed.slice(0,3).join(' | '):pricesOnly?'':'. Use Publish approved products to make approved products appear in the shop.'),failed.length>0);}
}
function checkSourceLabel(c){const source=c.result?.source;if(source==='official_pdf')return 'Official online price-guide PDF';if(source==='admin_pdf_upload')return 'Official guide uploaded by admin';if(source==='admin_confirmation')return 'Confirmed manually by admin';if(source==='official_public_page')return (courierNames[c.kind]||'Courier')+' public home-delivery prices';if(source==='service_pages')return c.kind==='royalmail'?'Royal Mail service pages':(courierNames[c.kind]||c.kind)+' service pages';return String(source||'').replaceAll('_',' ');}
function statusCards(){return state.checks.map(c=>`<article class="sc-check-card"><h3>${c.kind==='supplier'?'Supplier prices & availability':c.kind==='royalmail'?'Royal Mail online prices':esc(courierNames[c.kind]||c.kind)}</h3><strong>${esc(c.status.replaceAll('_',' '))}</strong><p>Last completed: ${date(c.completed_at)}<br>Next daily check: ${date(c.next_at)}</p>${c.result?.note?'<p>'+esc(c.result.note)+'</p>':''}${c.result?.checked!=null?`<p>${c.result.checked} checked · ${c.result.changed||0} changed · ${c.result.failed||0} need attention</p>`:''}${c.result?.source?`<p>Source: ${esc(checkSourceLabel(c))}${c.result.effective_from?' · effective '+esc(c.result.effective_from):''}</p>`:''}${c.error?`<p class="sc-warning">${esc(c.error)}</p>`:''}<button type="button" data-price-check="${c.kind}" ${c.status==='running'?'disabled':''}>${c.status==='running'?'Checking…':courierNames[c.kind]&&c.kind!=='inpost'?'Check source status':'Check prices now'}</button>${c.kind==='royalmail'?'<p><a href="https://www.royalmail.com/current-postage-prices" target="_blank" rel="noopener">Open official online price guide ↗</a></p><button type="button" data-manual-rates>Confirm rates manually</button><button type="button" data-upload-rates>Upload Royal Mail price guide</button><div id="scManualRates"></div>':''}</article>`).join('');}
function render(){
 if(!$('scApproveAll')){const b=document.createElement('button');b.id='scApproveAll';b.type='button';b.textContent='Approve all';b.onclick=()=>approveAll();$('shopPriceMissing').after(b);const prices=document.createElement('button');prices.id='scApprovePrices';prices.type='button';prices.textContent='Approve all prices';prices.onclick=()=>approveAll(undefined,true);b.after(prices);const fill=document.createElement('button');fill.id='scFillShipping';fill.type='button';fill.textContent='Fill missing weights & sizes';fill.onclick=()=>fillShipping();prices.after(fill);}
 renderFilters();
 $('shopPriceChecks').innerHTML=statusCards();checking=state.checks.some(c=>c.status==='running');
 const q=$('shopProductSearch').value.trim().toLowerCase(),products=state.products.filter(p=>matchesFilter(p)&&(p.name+' '+p.category+' '+productVariants(p).map(v=>v.name+' '+v.sku+' '+review.variantPublicationProblems(v).join(' ')).join(' ')).toLowerCase().includes(q));
 $('shopProductList').innerHTML=products.map(p=>`<button type="button" data-product="${esc(p.id)}" class="sc-product ${selected===p.id?'selected':''}">${photo(p)}<strong>${esc(p.name)}</strong><small>${esc(p.category)} · ${p.published?'Published':productBlockers(p).length?'Draft · Needs attention':'Approved · Ready to publish'}</small>${productBlockers(p).length?'<small class="sc-warning">'+esc(productBlockers(p)[0])+(productBlockers(p).length>1?' + '+(productBlockers(p).length-1)+' more':'')+'</small>':''}<span class="sc-profit-quick">${esc(productProfitText(p))}</span><small>No bulk discount · before payment fees and outgoing postage/packaging</small></button>`).join('')||'<p>No products match these filters.</p>';
 $('shopCatalogueCount').textContent=products.length+' of '+state.products.length+' products · '+state.variants.length+' total variants';
 $('shopRoyalRates').innerHTML=state.rates.filter(r=>!r.carrier_id).length?`<div class="table-wrap"><table><thead><tr><th>Service / size</th><th>Weight up to</th><th>Online price inc VAT</th><th>Change</th><th>Checked</th></tr></thead><tbody>${state.rates.filter(r=>!r.carrier_id).map(r=>`<tr><td><a href="${esc(r.source_url)}" target="_blank" rel="noopener">Royal Mail ${r.service==='tracked48'?'Tracked 48':'Tracked 24'}</a><br>${esc(r.format)} · ${dims(r.dimensions_mm)} mm</td><td>${r.max_g/1000} kg</td><td>${money(r.price_pence)}</td><td>${r.previous_pence==null?'—':money(r.price_pence-r.previous_pence)}</td><td>${date(r.checked_at)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Run Check prices now to load the confirmed Royal Mail online rates.</p>';
 $('shopPackagingList').closest('details').querySelector('summary').textContent='Saved packaging profiles (optional)';$('shopPackagingList').innerHTML='<p>Automatic delivery estimates work without these profiles. Keep any real packaging you use here as optional packing choices.</p>'+state.packages.map(p=>`<button type="button" data-package="${esc(p.id)}">${esc(p.name||p.id)} · ${dims(p.inner_mm)} mm · ${money(p.cost_pence)}${p.active?'':' · disabled'}</button>`).join('')||'<p>Add the packaging you actually use. Enter usable inner dimensions, outside dimensions, weight and all-in cost.</p>';
 renderCarriers();
 const c=state.config;$('shopPricingForm').innerHTML=`<fieldset><div class="sc-grid">${input('free_shipping_pence','Free standard delivery from (£)','50.00','number','readonly')}${input('stripe_bps','Stripe percentage fee (%)',c.stripe_bps/100,'number','min="0" max="90" step="0.01" required')}${input('stripe_reserve_bps','Extra payment-fee reserve (%)',c.stripe_reserve_bps/100,'number','min="0" max="90" step="0.01" required')}${input('stripe_fixed_pence','Stripe fixed fee (£)',pounds(c.stripe_fixed_pence),'number','min="0" step="0.01" required')}${input('min_profit_pence','Minimum order contribution (£)',pounds(c.min_profit_pence),'number','min="0.01" step="0.01" required')}${input('min_margin_bps','Minimum order margin (%)',c.min_margin_bps/100,'number','min="0" max="90" step="0.01" required')}${input('target_margin_bps','Target contribution margin (%)',c.target_margin_bps/100,'number','min="0" max="90" step="0.01" required')}${input('collection_pence','Optional collection cost per parcel (£)',pounds(c.collection_pence),'number','min="0" step="0.01" required')}${input('parcel_cost_allowance_pence','Estimated packaging cost per parcel (£)',pounds(c.parcel_cost_allowance_pence??50),'number','min="0" step="0.01" required')}${input('parcel_weight_allowance_g','Estimated extra parcel weight (g)',c.parcel_weight_allowance_g??100,'number','min="0" max="2000" step="1" required')}${input('parcel_dimension_allowance_mm','Estimated extra size on each parcel dimension (mm)',c.parcel_dimension_allowance_mm??10,'number','min="0" max="100" step="1" required')}</div><label>Bulk breaks — quantity : percentage off, one per line<textarea name="bulk">${c.bulk.map(b=>b.qty+' : '+b.bps/100).join('\n')}</textarea></label><p>Customer delivery fees are configured under Shop settings. These parcel allowances and courier rates estimate internal fulfilment costs only; they never add a customer surcharge. Measurements are optional estimates; review delivery suitability before approving a variant.</p><p>Contribution covers stock, inbound delivery, packaging, postage and the configured payment fee. It excludes your overheads and tax. Set the fee to cover the payment methods you accept.</p><button type="submit">Save pricing rules</button></fieldset>`;
}
async function load(silent=false){if(busy||dirty&&silent)return;const token=++seq;if(!silent)message('Loading Shop products…');try{await Promise.all([artworkReady,reviewReady,shippingReady]);const d=await request();if(token!==seq)return;state=d;render();if(!silent)message('Daily checks run on your backend. Product costs and supplier links are private to admin.');}catch(e){if(token===seq)message(e.message,true);}}
function showProduct(id,isNew=false){if(busy)return false;if(dirty&&!confirm('Discard unsaved changes?'))return false;dirty=false;selected=id;const p=state.products.find(p=>p.id===id)||{id:'',name:'',category:'Packaging supplies',description:'',specifications:[],version:null,published:false};$('shopProductEditor').hidden=false;
 $('shopProductEditor').innerHTML=`<h3>${isNew?'New product':esc(p.name)}</h3>${p.id?'<p><a href="https://inventoryos.co.uk/shop/product/'+encodeURIComponent(p.id)+'" target="_blank" rel="noopener">Open product URL ↗</a>'+(p.published?'':' · Available to customers after publication')+'</p>':''}${photo(p,true)}${p.id?publicationPanel(p):''}<form id="scProductForm"><fieldset><div class="sc-grid">${input('id','Product ID',p.id,'text',isNew?'pattern="[a-z0-9_-]+" required':'readonly')}${input('name','Product name',p.name,'text','required')}${input('category','Category',p.category,'text','required')}${input('image_url','Product image URL',(p.id==='jadens-668bt'?artwork?.productImage(p).src:p.image_url)||artwork?.productImage(p).src||'','url')}${input('image_rights','Image permission / licence reference',p.image_rights||(artwork?.productImage(p).illustration?artwork.illustrationRights:''))}</div><label>Description<textarea name="description" maxlength="4000">${esc(p.description)}</textarea></label><label>Specifications — heading | detail, one per line<textarea name="specifications">${esc(p.specifications.map(x=>x.join(' | ')).join('\n'))}</textarea></label>${checkbox('published','Publish after all variant checks pass',p.published)}<button type="submit">Save product</button></fieldset></form><h4>Variants${filterName()!=='all'?' — '+esc(review.catalogueFilters.find(f=>f[0]===filterName())?.[1]||'Filtered'):''}</h4>${filterName()!=='all'?'<button type="button" id="scShowAllVariants">Show all variants</button>':''}${p.id?'<button type="button" id="scApproveProduct">Approve all variants</button> <button type="button" id="scApproveProductPrices">Approve all prices</button> <button type="button" id="scFillProductShipping">Fill missing weights & sizes</button>':''}<p class="sc-profit-note">Profit uses the normal selling price, supplier cost, and inbound delivery. No bulk discount. Payment fees, outgoing postage and packaging are excluded.</p><p>Supplier cost is the cost of one pack we sell, including unrecoverable VAT. Inbound delivery is its separate allocated supplier-delivery cost. The price checker refreshes supplier cost; no separate purchase cost is needed.</p><div class="table-wrap"><table><thead><tr><th>Variant / stock</th><th>Latest supplier cost / minimum order</th><th>Sell price</th><th>Profit / selling pack<br>No bulk discount</th><th>Minimum-order contribution</th><th>Review</th></tr></thead><tbody>${shownVariants(p).map(v=>`<tr><td><button type="button" data-variant="${esc(v.id)}">${esc(v.name)}</button><br>${esc(v.sku)} · ${esc(supplierAvailabilityText(v))}${v.supplier_url?`<br><a href="${esc(v.supplier_url)}" target="_blank" rel="noopener">Supplier product ↗</a>`:''}</td><td>${money(v.replacement_cost_pence)} per selling pack<br>Inbound: ${money(v.inbound_pence)}<br>${supplierBasis(v)}${v.previous_supplier_pence!=null?'<br>Previous: '+money(v.previous_supplier_pence):''}<small>${date(v.checked_at)}</small></td><td>${money(v.price_pence)}${v.price_estimated?'<small class="sc-warning">Provisional — review price</small>':''}${v.price_note?'<small>'+esc(v.price_note)+'</small>':''}</td><td>${esc(profitText(v))}</td><td>${v.preview?money(v.preview.profit_pence)+' / '+(v.preview.margin_bps/100).toFixed(1)+'%':esc(v.preview_error||'Needs measurements')}</td><td>${review.needsApproval(v)?'Review required':'Approved'}${review.approvalProblems(v).length?'<small class="sc-warning">'+esc(review.approvalProblems(v).join(' · '))+'</small>':''}${shippingReference(v,true)}${v.check_error?'<p class="sc-warning">'+esc(v.check_error)+'</p>':''}</td></tr>`).join('')}</tbody></table></div>${p.id?'<button id="scAddVariant" type="button">Add variant</button>':''}<div id="scVariantEditor"></div>`;
 $('scProductForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);save('/products',{...p,id:f.get('id'),name:f.get('name'),category:f.get('category'),image_url:f.get('image_url'),image_rights:f.get('image_rights'),description:f.get('description'),specifications:String(f.get('specifications')).split('\n').filter(x=>x.trim()).map(x=>x.split('|').map(y=>y.trim())),published:f.has('published')},e.target,()=>showProduct(f.get('id')));};
 if($('scPublishProduct'))$('scPublishProduct').onclick=()=>publishApproved(p.id);if($('scShowAllVariants'))$('scShowAllVariants').onclick=()=>{$('scProductFilter').value='all';showProduct(p.id);};
 if($('scFillProductShipping'))$('scFillProductShipping').onclick=()=>fillShipping(p.id);if($('scApproveProduct'))$('scApproveProduct').onclick=()=>approveAll(p.id);if($('scApproveProductPrices'))$('scApproveProductPrices').onclick=()=>approveAll(p.id,true);if($('scAddVariant'))$('scAddVariant').onclick=()=>showVariant(null,p.id);render();return true;
}
function uploadRates(){
 if(!state||busy)return;if(dirty&&!confirm('Discard unsaved changes?'))return;dirty=false;
 const job=state.checks.find(c=>c.kind==='royalmail');$('scManualRates').innerHTML=`<form id="scUploadRatesForm"><fieldset><h4>Upload the current official online guide</h4><p>Open the official guide link above, download the Royal Mail online price-guide PDF, then choose it here. InventoryOS checks its date, UK Tracked tables and size limits. This is recorded as an admin upload; automatic checks keep running daily.</p><label>Royal Mail online guide PDF (maximum 2.5 MB)<input name="pdf" type="file" accept=".pdf,application/pdf" required></label>${checkbox('confirmed','I downloaded this unmodified PDF from Royal Mail and checked it is the current online price guide.',false)}<button type="submit">Read PDF and save prices</button></fieldset></form>`;
 $('scUploadRatesForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const form=e.target,file=form.elements.pdf.files[0];if(!form.elements.confirmed.checked){message('Confirm this is the current official Royal Mail online guide.',true);return;}if(!file||file.size>2500000){message('Choose a PDF no larger than 2.5 MB.',true);return;}busy=true;form.querySelector('fieldset').disabled=true;message('Reading Royal Mail price guide…');try{const pdf=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Could not read this PDF.'));reader.readAsDataURL(file);});await request('/royalmail/pdf',{pdf_base64:pdf,confirmed:true,previous_completed_at:job?.completed_at?new Date(job.completed_at).toISOString():''});dirty=false;busy=false;await load(true);message('All ten Royal Mail prices imported from your guide.');}catch(e){message(e.message,true);}finally{busy=false;form.querySelector('fieldset').disabled=false;}};
 $('scManualRates').scrollIntoView({block:'nearest',behavior:'smooth'});
}
function manualRates(){
 if(!state||busy)return;if(dirty&&!confirm('Discard unsaved changes?'))return;dirty=false;
 const job=state.checks.find(c=>c.kind==='royalmail'),rows=['tracked48','tracked24'].flatMap(service=>[['large-letter',1000],['small',2000],['medium',2000],['medium',10000],['medium',20000]].map(([format,max_g])=>({id:service+'-'+format+'-'+max_g,service,format,max_g})));
 $('scManualRates').innerHTML=`<form id="scManualRatesForm"><fieldset><h4>Confirm the current online prices</h4><p>Use the official online guide, including VAT, without signature. Values below are your last saved prices, if available. This records a manual confirmation; it does not pretend an automatic check succeeded.</p><div class="sc-grid">${rows.map(r=>input(r.id,(r.service==='tracked48'?'Tracked 48':'Tracked 24')+' · '+r.format+' · '+r.max_g/1000+'kg',pounds(state.rates.find(x=>x.id===r.id)?.price_pence),'number','min="0.50" max="100" step="0.01" required')).join('')}</div>${checkbox('confirmed','I checked all ten prices against the current official online guide, including VAT and without signature.',false)}<button type="submit">Confirm and save rates</button><button type="button" id="scCancelRates">Cancel</button></fieldset></form>`;
 $('scCancelRates').onclick=()=>{if(!dirty||confirm('Discard these rate changes?')){dirty=false;$('scManualRates').innerHTML='';}};
 $('scManualRatesForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.has('confirmed')){message('Check the official guide and tick the confirmation box.',true);return;}save('/royalmail/confirm',{confirmed:true,previous_completed_at:job?.completed_at?new Date(job.completed_at).toISOString():'',rates:rows.map(r=>({id:r.id,price_pence:parsePence(f.get(r.id))}))},e.target);};
 $('scManualRates').scrollIntoView({block:'nearest',behavior:'smooth'});
}
const parsePence=v=>v===''?null:Math.round(Number(v)*100),parseDims=v=>v.trim()?v.split(/[x×,\s]+/).filter(Boolean).map(Number):null;
function showVariant(id,productId){if(busy)return;if(dirty&&!confirm('Discard unsaved changes?'))return;dirty=false;const v=state.variants.find(v=>v.id===id)||{id:'',product_id:productId,name:'',sku:'',stock:0,inbound_pence:0,supplier_vat_bps:2000};$('scVariantEditor').innerHTML=`<form id="scVariantForm"><h4>${id?'Edit variant':'New variant'}</h4><p class="sc-profit-quick">${esc(profitText(v))} · No bulk discount; before payment fees and outgoing postage/packaging.</p>${photo(state.products.find(p=>p.id===v.product_id)||{id:v.product_id,name:'Product',category:''},true,v)}<fieldset><div class="sc-grid">${input('id','Variant ID',v.id,'text',id?'readonly':'required pattern="[a-z0-9_-]+"')}${input('name','Variant / size / pack quantity',v.name,'text','required')}${input('sku','SKU',v.sku,'text','required')}${input('supplier_url','Supplier product link',v.supplier_url||'','url')}${input('supplier_variant_id','Supplier variant ID (for exact price checks)',v.supplier_variant_id||'')}${input('supplier_vat_bps','Supplier VAT (%)',v.supplier_vat_bps/100,'number','min="0" max="100" step="0.01" required')}${input('supplier_price_units','Units covered by one supplier price',v.supplier_price_units??1,'number','min="1" max="1000000" step="1" required')}${input('supplier_min_order_qty','Minimum supplier quantity (priced units or packs)',v.supplier_min_order_qty??1,'number','min="1" max="1000000" step="1" required')}${input('sale_units_per_pack','Units in each pack WE sell',v.sale_units_per_pack??1,'number','min="1" max="1000000" step="1" required')}${input('supplier_unit_name','Unit description (e.g. boxes, rolls)',v.supplier_unit_name||'units','text','maxlength="40" required')}${input('replacement_cost_pence','Supplier cost per OUR selling pack inc VAT (£)',pounds(v.replacement_cost_pence),'number','min="0" step="0.01"')}${input('inbound_pence','Inbound delivery allocated per pack (£)',pounds(v.inbound_pence),'number','min="0" step="0.01" required')}${input('price_pence','Sell price per pack (£)',pounds(v.price_pence),'number','min="0.01" step="0.01"')}<p>${esc(supplierAvailabilityText(v))}</p><button type="button" id="scConfirmSupplier">Confirm supplier availability</button>${input('dimensions_mm','Protected sellable pack L × W × H (mm)',dims(v.dimensions_mm))}${input('weight_g','Protected sellable pack weight (g)',v.weight_g||'','number','min="1" max="70000" step="1"')}</div><p>Per-box price with a minimum of five: supplier units 1, minimum 5. Price for a pack of 50: supplier units 50, minimum 1. Set our selling pack to 1 for individual boxes or 50 for a full pack. Minimum purchase excludes supplier delivery. Existing stock is counted in our selling packs; supplier availability is checked for the exact selling pack.</p>${checkbox('supplier_price_includes_vat','Supplier source price already includes VAT',v.supplier_price_includes_vat)}${checkbox('price_confirmed','I have reviewed the selling price and its delivery costs',!v.price_estimated)}<div id="scPriceEstimate" role="status">${esc(v.price_note||'')}</div>${id?'<button type="button" id="scCalculatePrice">Calculate suggested selling price</button>':''}${checkbox('cost_verified','I have checked supplier costs and pack contents',v.cost_verified)}${shippingReference(v)}${checkbox('shipping_verified','I have reviewed delivery suitability and any available pack estimates',v.shipping_verified)}${checkbox('free_shipping','Eligible for free standard delivery',v.free_shipping!==false)}<button type="submit">Save variant</button><button type="button" id="scCancelVariant">Close variant</button></fieldset></form><div id="scSupplierEditor"></div>`;
 if($('scConfirmSupplier'))$('scConfirmSupplier').onclick=()=>confirmSupplierAvailability(v);
 if($('scCalculatePrice'))$('scCalculatePrice').onclick=async()=>{if(dirty){message('Save the variant first so the calculation uses your latest pack size, costs and measurements.',true);return;}if(busy)return;const form=$('scVariantForm');busy=true;form.querySelector('fieldset').disabled=true;message('Calculating selling price…');try{const r=(await request('/prices/recommend',{id:v.id})).result;if(!form.isConnected)return;form.elements.price_pence.value=pounds(r.price_pence);form.elements.price_confirmed.checked=false;v.price_estimated=true;v.price_note=r.note;$('scPriceEstimate').textContent=money(r.price_pence)+' · '+r.note;dirty=true;message('Suggested price filled in. Review it, tick the price confirmation and save.');}catch(e){message(e.message,true);}finally{busy=false;form.querySelector('fieldset').disabled=false;}};
 $('scCancelVariant').onclick=()=>{if(!dirty||confirm('Discard unsaved variant changes?')){dirty=false;$('scVariantEditor').innerHTML='';}};
 $('scVariantForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),b={...v,id:f.get('id'),name:f.get('name'),sku:f.get('sku'),supplier_url:f.get('supplier_url'),supplier_variant_id:f.get('supplier_variant_id'),dimensions_mm:parseDims(f.get('dimensions_mm')),weight_g:f.get('weight_g')?Number(f.get('weight_g')):null};b.cost_pence=v.cost_pence??null;for(const k of ['replacement_cost_pence','inbound_pence','price_pence'])b[k]=parsePence(f.get(k));b.supplier_vat_bps=Math.round(Number(f.get('supplier_vat_bps'))*100);b.stock=v.stock??0;b.fulfilment_mode=v.fulfilment_mode??'supplier';for(const k of ['supplier_price_units','supplier_min_order_qty','sale_units_per_pack'])b[k]=Number(f.get(k));b.supplier_unit_name=f.get('supplier_unit_name');for(const k of ['cost_verified','shipping_verified','free_shipping','supplier_price_includes_vat','price_confirmed'])b[k]=f.has(k);save('/variants',b,e.target,()=>showProduct(v.product_id));};
 $('scVariantEditor').scrollIntoView({block:'nearest',behavior:'smooth'});
}
async function save(route,body,form,done){if(busy)return;busy=true;form.querySelector('fieldset').disabled=true;message('Saving…');try{await request(route,body);dirty=false;busy=false;await load(true);done?.();message('Saved.');}catch(e){message(e.message,true);}finally{busy=false;form.querySelector('fieldset')?.removeAttribute('disabled');}}
function editPackage(id){if(dirty&&!confirm('Discard unsaved changes?'))return;dirty=false;const p=state.packages.find(p=>p.id===id)||{id:'',weight_g:0,cost_pence:0,active:true};$('shopPackagingEditor').innerHTML=`<form id="scPackageForm"><fieldset><div class="sc-grid">${input('id','Packaging ID',p.id,'text',id?'readonly':'required pattern="[a-z0-9_-]+"')}${input('name','Packaging name',p.name||'')}${input('inner_mm','Usable inner L × W × H (mm)',dims(p.inner_mm),'text','required')}${input('outer_mm','Outside L × W × H (mm)',dims(p.outer_mm),'text','required')}${input('weight_g','Packaging weight including void fill (g)',p.weight_g,'number','min="0" step="1" required')}${input('cost_pence','Packaging cost including void fill (£)',pounds(p.cost_pence),'number','min="0" step="0.01" required')}</div>${checkbox('active','Use for packing calculations',p.active)}<button type="submit">Save packaging</button></fieldset></form>`;$('scPackageForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);save('/packaging',{id:f.get('id'),name:f.get('name'),inner_mm:parseDims(f.get('inner_mm')),outer_mm:parseDims(f.get('outer_mm')),weight_g:Number(f.get('weight_g')),cost_pence:parsePence(f.get('cost_pence')),active:f.has('active')},e.target,()=>{$('shopPackagingEditor').innerHTML='';});};}
$('shopProductSearch').addEventListener('input',()=>state&&render());$('shopCatalogueRefresh').onclick=()=>{if(!dirty||confirm('Discard unsaved changes?')){dirty=false;$('shopProductEditor').hidden=true;load();}};$('shopPriceMissing').onclick=async()=>{if(dirty){message('Save your current changes first.',true);return;}if(busy)return;busy=true;$('shopPriceMissing').disabled=true;try{const r=await request('/prices/missing',{});busy=false;await load(true);if(selected)showProduct(selected);message(r.result.count+' missing selling prices filled. Provisional prices must be reviewed before publication.');}catch(e){message(e.message,true);}finally{busy=false;$('shopPriceMissing').disabled=false;}};$('shopAddProduct').onclick=()=>state&&showProduct('',true);$('shopAddPackaging').onclick=()=>state&&editPackage('');
section.addEventListener('input',e=>{if(e.target.closest('form'))dirty=true;});
section.addEventListener('click',async e=>{const carrier=e.target.closest('[data-carrier-edit]');if(carrier)editCarrier(carrier.dataset.carrierEdit);const p=e.target.closest('[data-product]'),v=e.target.closest('[data-variant]'),pack=e.target.closest('[data-package]'),check=e.target.closest('[data-price-check]');if(e.target.closest('[data-manual-rates]'))manualRates();if(e.target.closest('[data-upload-rates]'))uploadRates();if(p&&showProduct(p.dataset.product)){const matching=shownVariants(state.products.find(x=>x.id===p.dataset.product));if(filterName()!=='all'&&matching.length===1&&$('scVariantEditor')){showVariant(matching[0].id);const focusField={price:'price_pence',cost:'replacement_cost_pence',dimensions:'dimensions_mm',measurements:review.measurementProblems(matching[0]).includes('Pack measurements needed')?'dimensions_mm':'weight_g',weight:'weight_g',supplier:'supplier_url',source:'supplier_variant_id',stock:'stock',outofstock:'stock',packs:'supplier_price_units'}[filterName()];if(focusField)$('scVariantForm')?.elements[focusField]?.focus();}}if(v)showVariant(v.dataset.variant);if(pack)editPackage(pack.dataset.package);if(check){check.disabled=true;message('Starting price check…');try{await request('/check/'+check.dataset.priceCheck,{});message('Price check running. You can keep using the Shop.');checking=true;clearInterval(poll);poll=setInterval(()=>{if(!dirty&&!busy)load(true);if(!checking){clearInterval(poll);if(selected&&!dirty)showProduct(selected);}},3000);setTimeout(()=>load(true),500);}catch(err){message(err.message,true);check.disabled=false;}}});
$('shopPricingForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),config={...state.config};for(const k of ['free_shipping_pence','stripe_fixed_pence','min_profit_pence','collection_pence','parcel_cost_allowance_pence'])config[k]=parsePence(f.get(k));for(const k of ['stripe_bps','stripe_reserve_bps','min_margin_bps','target_margin_bps'])config[k]=Math.round(Number(f.get(k))*100);for(const k of ['parcel_weight_allowance_g','parcel_dimension_allowance_mm'])config[k]=Number(f.get(k));config.bulk=String(f.get('bulk')).split('\n').filter(x=>x.trim()).map(x=>{const [qty,pct]=x.split(':').map(Number);return {qty,bps:Math.round(pct*100)};});save('/settings',{config,version:state.settings_version},e.target);};
document.addEventListener('inventoryos-admin-tab',e=>{if(e.detail==='shopCatalogue'&&!state)load();});
})();
